B.bkd=s(["\u0432\u043e\u0434\u043d\u044b\u0439","\u043b\u0435\u0441\u043d\u043e\u0439","\u0434\u043e\u043c\u0438\u043a","\u0432\u043e\u0434\u0438\u0447\u043a\u0430","\u043b\u0435\u0441\u043d\u0438\u043a","\u0434\u043e\u043c\u043e\u0432\u043e\u0439","\u043f\u043e\u0434\u0432\u043e\u0434\u043d\u0438\u043a","\u043b\u0435\u0441\u043e\u0447\u0435\u043a"],t.s)
